const game = new GF.Game({
    id: 'core-awakening',
    title: 'Core Awakening',
    width: 960,
    height: 540,
    palette: ['#00BFFF', '#FFA500', '#A9A9A9', '#800000'],
    background: '#000000'
});

let player, enemies, particles, salvageOptions;

const createPlayer = () => {
    return {
        x: game.W / 2,
        y: game.H / 2,
        size: 20,
        color: game.palette[0],
        speed: 200,
        health: 100
    };
};

const createEnemy = () => {
    const x = Math.random() > 0.5 ? -50 : game.W + 50;
    const y = Math.random() * game.H;
    return {
        x,
        y,
        size: 30,
        color: game.palette[1],
        speed: 100,
        health: 50,
        attackTimer: 0
    };
};

const init = () => {
    player = createPlayer();
    enemies = [createEnemy()];
    particles = new GF.Particles();
    salvageOptions = [];
};

const reset = () => {
    init();
};

const update = (dt) => {
    const input = game.input;
    if (input.keys['KeyW']) player.y -= player.speed * dt;
    if (input.keys['KeyS']) player.y += player.speed * dt;
    if (input.keys['KeyA']) player.x -= player.speed * dt;
    if (input.keys['KeyD']) player.x += player.speed * dt;
    player.x = GF.math.clamp(player.x, 0, game.W);
    player.y = GF.math.clamp(player.y, 0, game.H);

    for (const enemy of enemies) {
        enemy.x += (player.x > enemy.x ? 1 : -1) * enemy.speed * dt;
        enemy.y += (player.y > enemy.y ? 1 : -1) * enemy.speed * dt;
        enemy.attackTimer += dt;
        if (enemy.attackTimer > 2) {
            enemy.attackTimer = 0;
            if (GF.math.dist(player.x, player.y, enemy.x, enemy.y) < 50) {
                player.health -= 10;
                game.shake(5, 0.2);
                GF.Sfx.noise({ dur: 0.2, vol: 0.5 });
                if (player.health <= 0) {
                    game.gameOver({ message: 'Core Destroyed' });
                }
            }
        }
    }

    if (input.pointer.clicked) {
        for (const enemy of enemies) {
            if (GF.math.dist(input.pointer.x, input.pointer.y, enemy.x, enemy.y) < enemy.size) {
                enemy.health -= 20;
                game.hitStop(0.1);
                game.burst(enemy.x, enemy.y, { count: 10, speed: 100, size: 5, life: 0.5, colors: [game.palette[2]] });
                GF.Sfx.beep({ freq: 300, dur: 0.1 });
                if (enemy.health <= 0) {
                    game.addScore(100);
                    game.flash('#FF0000', 0.5);
                    game.shake(8, 0.3);
                    GF.Sfx.melody([[440, 0.1], [660, 0.1]]);
                    salvageOptions.push({ x: enemy.x, y: enemy.y, timer: 3 });
                    enemies.splice(enemies.indexOf(enemy), 1);
                }
            }
        }
    }

    for (const option of salvageOptions) {
        option.timer -= dt;
        if (option.timer <= 0) {
            salvageOptions.splice(salvageOptions.indexOf(option), 1);
        }
    }

    if (enemies.length < 3 && Math.random() < 0.01) {
        enemies.push(createEnemy());
    }

    particles.update(dt);
};

const draw = (ctx) => {
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, game.W, game.H);

    ctx.fillStyle = player.color;
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.size, 0, GF.math.TAU);
    ctx.fill();

    for (const enemy of enemies) {
        ctx.fillStyle = enemy.color;
        ctx.beginPath();
        ctx.arc(enemy.x, enemy.y, enemy.size, 0, GF.math.TAU);
        ctx.fill();
    }

    for (const option of salvageOptions) {
        ctx.strokeStyle = '#FFF';
        ctx.beginPath();
        ctx.arc(option.x, option.y, 40, 0, GF.math.TAU);
        ctx.stroke();
    }

    particles.draw(ctx);

    GF.Draw.text(ctx, `Health: ${player.health}`, 10, 30, { size: 20, color: '#FFF', align: 'left' });
    GF.Draw.text(ctx, `Score: ${game.score}`, game.W - 10, 30, { size: 20, color: '#FFF', align: 'right' });
};

const playScene = { init, reset, update, draw };
game.add('play', playScene);
game.titleScreen({ subtitle: 'Press any key to start', onStart: () => game.go('play') });
